<?php
$connection = db();
$stats = $connection->query("SELECT (SELECT COUNT(*) FROM orders WHERE status='new') new_orders, (SELECT COUNT(*) FROM orders WHERE payment_status='pending' AND status <> 'cancelled') pending_payments, (SELECT COUNT(*) FROM products WHERE stock_quantity <= reorder_level) low_stock, COALESCE((SELECT SUM(total_amount) FROM orders WHERE status='completed'),0) revenue")->fetch_assoc();
$orders = $connection->query("SELECT o.*, GROUP_CONCAT(CONCAT(oi.quantity, ' x ', oi.product_name) SEPARATOR ', ') items FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id ORDER BY FIELD(o.status,'new','confirmed','processing','ready','completed','cancelled'),o.created_at DESC LIMIT 10")->fetch_all(MYSQLI_ASSOC);
$lowStock = $connection->query('SELECT name, stock_quantity, reorder_level FROM products WHERE stock_quantity <= reorder_level ORDER BY stock_quantity, name LIMIT 6')->fetch_all(MYSQLI_ASSOC);
$success = flash('success'); $error = flash('error');
echo '<style>.ops-brand span{display:none!important}.ops-brand:before{content:"";width:40px;height:40px;border-radius:50%;background:#07182e url("../assets/images/sammy-tech-logo.jpeg") center/cover no-repeat;box-shadow:0 0 0 2px #0ea5e9;flex:none}</style><script>document.addEventListener("DOMContentLoaded",function(){var nav=document.querySelector(".ops-sidebar nav");if(!nav)return;var installations=nav.querySelector("a[href=\\"installations.php\\"]");if(!nav.querySelector("a[href=\\"orders.php\\"]")){var orders=document.createElement("a");orders.href="orders.php";orders.textContent="Orders and payments";nav.insertBefore(orders,installations);}if(!nav.querySelector("a[href=\\"backup.php\\"]")){var backup=document.createElement("a");backup.href="backup.php";backup.textContent="Backups";nav.appendChild(backup);}if(!nav.querySelector("a[href=\\"profile.php\\"]")){var profile=document.createElement("a");profile.href="profile.php";profile.textContent="My account";nav.appendChild(profile);}if(!nav.querySelector("a[href=\\"users.php\\"]")){var users=document.createElement("a");users.href="users.php";users.textContent="Staff users";nav.appendChild(users);}});</script>';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Sammy Tech | Operations</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="../assets/css/dashboard.css"></head><body><div class="ops-layout"><aside class="ops-sidebar"><a class="ops-brand" href="index.php"><span>ST</span><b>Sammy Tech</b></a><p class="ops-label">Main menu</p><nav><a class="active" href="index.php">Overview</a><a href="catalog.php">Products</a><a href="installations.php">Installations</a><a href="reports.php">Reports</a></nav><div class="sidebar-help"><b>Customer view</b><a href="../index.php" target="_blank">Open storefront -></a></div><form class="ops-logout" action="logout.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button>Sign out</button></form></aside><main class="ops-main"><header class="ops-header"><div><p>OPERATIONS CENTRE</p><h1>Today at a glance.</h1><span>Review orders first, then payment and stock alerts.</span></div><time><?=e(date('l, d M Y'))?><small>Juba, South Sudan</small></time></header><?php if($success):?><div class="ops-alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="ops-alert error"><?=e($error)?></div><?php endif;?><section class="priority-grid"><article class="orange"><span>New orders</span><strong><?=e((string)$stats['new_orders'])?></strong><p>Review customer requests.</p><a href="#orders">Open queue -></a></article><article class="yellow"><span>Awaiting payment</span><strong><?=e((string)$stats['pending_payments'])?></strong><p>Verify references or proof.</p><a href="#orders">Check payments -></a></article><article class="blue"><span>Low stock</span><strong><?=e((string)$stats['low_stock'])?></strong><p>Items at reorder level.</p><a href="#stock">View stock -></a></article><article class="dark"><span>Completed sales</span><strong><?=money((float)$stats['revenue'])?></strong><p>Revenue from completed orders.</p><a href="reports.php">Open reports -></a></article></section><section class="work-grid"><section class="orders-panel" id="orders"><div class="section-bar"><div><p>ORDER WORK QUEUE</p><h2>What needs attention</h2></div><span><?=count($orders)?> recent orders</span></div><?php if(!$orders):?><div class="empty-state"><b>No orders yet.</b><p>New customer orders will appear here.</p></div><?php else:?><div class="order-list"><?php foreach($orders as $order):?><article class="order-row"><div class="order-id"><b><?=e($order['order_number'])?></b><span><?=e(date('d M, H:i',strtotime($order['created_at'])))?></span></div><div class="order-customer"><b><?=e($order['customer_name'])?></b><span><?=e($order['phone'])?></span></div><div class="order-items"><?=e($order['items']?:'No items')?></div><div class="order-total"><b><?=money((float)$order['total_amount'])?></b><span><?=e(ucwords(str_replace('_',' ',$order['delivery_method'])))?></span></div><div class="order-state"><span class="tag tag-<?=e($order['status'])?>"><?=e($order['status'])?></span><span class="payment <?=e($order['payment_status'])?>">Payment: <?=e($order['payment_status'])?></span></div><div class="order-actions"><form action="order_action.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=e((string)$order['id'])?>"><input type="hidden" name="action" value="status"><select name="status"><?php foreach(['new','confirmed','processing','ready','completed','cancelled'] as $status):?><option value="<?=$status?>" <?=$order['status']===$status?'selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select><button>Update</button></form><form action="order_action.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=e((string)$order['id'])?>"><input type="hidden" name="action" value="payment"><select name="payment_status"><?php foreach(['pending','paid','failed','refunded'] as $payment):?><option value="<?=$payment?>" <?=$order['payment_status']===$payment?'selected':''?>><?=ucfirst($payment)?></option><?php endforeach;?></select><button class="secondary">Payment</button></form></div></article><?php endforeach;?></div><?php endif;?></section><aside class="stock-watch" id="stock"><div><p>INVENTORY WATCH</p><h2>Restock soon</h2></div><?php if($lowStock):?><div class="stock-list"><?php foreach($lowStock as $product):?><div><i></i><p><b><?=e($product['name'])?></b><small>Reorder at <?=e((string)$product['reorder_level'])?></small></p><strong><?=e((string)$product['stock_quantity'])?> left</strong></div><?php endforeach;?></div><a href="catalog.php">Manage product stock -></a><?php else:?><div class="stock-good"><b>All clear.</b><p>No product is below its reorder level.</p></div><?php endif;?></aside></section></main></div></body></html>
